 function stopAudio(){speechEpoch++;if(ownSpeech&&'speechSynthesis'in window)speechSynthesis.cancel();ownSpeech=false;context?.root.querySelectorAll('[data-grammar-speaking]').forEach(n=>n.removeAttribute('data-grammar-speaking'));}
